const products=[{name:'Radeon RX 7800 XT 16 GB',category:'Tarjetas de video',price:649990,detail:'16 GB GDDR6 · 256 bits · Boost hasta 2565 MHz',type:'gpu',stock:3,tag:'MÁS FPS. MÁS VICTORIAS.',description:'16 GB GDDR6 y boost de hasta 2565 MHz.<br>Potencia tu equipo con Radeon RX 7800 XT.'},{name:'Silla Ejecutiva LEVO Negra',category:'Sillas gamer',price:100000,demo:false,detail:'Ecocuero negro · Altura ajustable · Hasta 120 kg',type:'chair-levo',stock:8,tag:'COMODIDAD PARA TU ESPACIO',description:'Comodidad, estilo y funcionalidad.<br>Equipa tu oficina o espacio de home office.'},{name:'AMD Ryzen 7 9700X',category:'Procesadores',price:399990,detail:'8 núcleos · 16 hilos · Hasta 5.5 GHz · AM5',type:'cpu',stock:5,tag:'POTENCIA EN CADA JUGADA',description:'Arquitectura Zen 5, 8 núcleos y 16 hilos.<br>Potencia tu escritorio con AMD Ryzen 7 9700X.'},{name:'Gigabyte B650E EAGLE WIFI6E',category:'Tarjetas madres',price:249990,detail:'AM5 · DDR5 · 3 M.2 · PCIe 5.0 · Wi-Fi 6E',type:'board',stock:2,tag:'UNA BASE PARA IR MÁS LEJOS',description:'Socket AM5, DDR5 y PCIe 5.0.<br>Conecta tu equipo con Wi-Fi 6E y LAN de 2.5 GbE.'},{name:'Royal Kludge RK918 Black Brown Switch',category:'Periféricos',price:69990,detail:'104 teclas · Switch RK Brown · RGB · USB 2.0',type:'keyboard',stock:3,tag:'CADA TECLA CUENTA',description:'104 teclas, switches RK Brown y RGB.<br>Un teclado completo para jugar, trabajar y crear.'}];
const money=n=>'$'+n.toLocaleString('es-CL');const wa=p=>'https://wa.me/56966274175?text='+encodeURIComponent('Hola Fusionia, quiero consultar por '+p.name+(p.demo===false?' (precio ':' (precio de demostración ')+money(p.price)+').');
function art(type){if(type==='keyboard')return '<img class="hardware product-photo" src="assets/teclado-transparente.png" alt="Teclado mecánico Royal Kludge RK918 negro con switches Brown y RGB">';if(type==='board')return '<img class="hardware product-photo" src="assets/placabase.webp" alt="Placa madre Gigabyte B650E EAGLE WIFI6E con socket AM5">';if(type==='gpu')return '<img class="hardware product-photo" src="assets/670.webp" alt="Tarjeta de video Radeon RX 7800 XT de 16 GB GDDR6">';if(type==='cpu')return '<img class="hardware product-photo" src="assets/ryzen7.png" alt="AMD Ryzen 7 9700X, procesador de 8 núcleos para socket AM5">';if(type==='chair-levo')return '<img class="hardware product-photo" src="assets/silla-levo-transparente.png" alt="Silla Ejecutiva LEVO Negra en ecocuero, con apoyabrazos y base con ruedas" width="1024" height="1024">';let shapes='';if(type==='chair'){shapes='<path d="M215 232v48m0-12-65 20m65-20 65 20m-65-20v30" stroke="#59644e" stroke-width="11"/><path d="M169 156h106l26 72q-70 32-156 0Z" fill="#252c23" stroke="#778269" stroke-width="3"/><path d="M170 171L158 66 181 26h69l24 40-10 110Z" fill="url(#metal)" stroke="#6f7f5c" stroke-width="3"/><path d="M179 39l-8 27 14 97m58-124 16 30-13 93" fill="none" stroke="#c4ff45" stroke-width="7"/><path d="M190 58h38v20h-38z" fill="#080d08"/><path d="M145 185l-20-7v-27h31m125 34 25-7v-27h-29" fill="none" stroke="#5f6c53" stroke-width="9"/><path d="M169 220q47 17 102 0" fill="none" stroke="#c4ff45" stroke-width="4"/>'}return `<svg class="hardware" viewBox="0 0 500 330" role="img" aria-label="Ilustración referencial de ${type==='gpu'?'tarjeta gráfica':type==='chair'?'silla gamer':type==='cpu'?'procesador':type==='board'?'tarjeta madre':'teclado'}"><defs><linearGradient id="metal" x2=".3" y2="1"><stop stop-color="#56614c"/><stop offset=".5" stop-color="#242d23"/><stop offset="1" stop-color="#101711"/></linearGradient><linearGradient id="silver" x2="1" y2="1"><stop stop-color="#d8dfd3"/><stop offset=".5" stop-color="#899581"/><stop offset="1" stop-color="#c1cab9"/></linearGradient></defs>${shapes}</svg>`}
const track=document.getElementById('product-track'),stage=document.getElementById('scroll-stage');let selected='Todos',slide=0,timer;const cats=['Todos','Sillas gamer','Procesadores','Tarjetas madres','Tarjetas de video','Periféricos'];document.getElementById('categorias').innerHTML=cats.map((c,i)=>`<button class="${i===0?'active':''}" data-category="${c}">${c}</button>`).join('');
function render(){track.innerHTML=products.filter(p=>selected==='Todos'||p.category===selected).map(p=>`<article class="product-card"><div class="card-top"><b>UPGRADE / ${String(products.indexOf(p)+1).padStart(2,'0')}</b><span>${p.demo===false?'LEVO':'DEMO'}</span></div><div class="card-art">${art(p.type)}</div><div class="card-info"><span>${p.category.toUpperCase()}</span><h3>${['chair-levo','cpu','gpu','board','keyboard'].includes(p.type)?'<button type="button" class="product-title-link" data-product-details="'+p.type+'">'+p.name+'</button>':p.name}</h3><p>${p.detail}</p><div class="card-price"><strong>${money(p.price)}</strong><a href="${wa(p)}" target="_blank" rel="noopener" aria-label="Consultar por ${p.name}">↗</a></div>${['chair-levo','cpu','gpu','board','keyboard'].includes(p.type)?'<button type="button" class="product-details-link" data-product-details="'+p.type+'">Ver ficha del producto ↗</button>':''}<button type="button" class="add-to-cart" data-add-product="${p.type}" aria-label="Agregar ${p.name} al carrito">Agregar al carrito <span>+</span></button></div></article>`).join('');resize();}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{selected=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));render()});
function resize(){const extra=Math.max(0,track.scrollWidth-track.parentElement.clientWidth);stage.style.height=extra?extra+track.offsetHeight+130+'px':'auto';updateScroll()}
function updateScroll(){const extra=Math.max(0,track.scrollWidth-track.parentElement.clientWidth);const progress=Math.min(1,Math.max(0,(20-stage.getBoundingClientRect().top)/(stage.offsetHeight-track.offsetHeight-40||1)));track.style.transform=`translateX(${-extra*(1-progress)}px)`}
window.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('resize',resize);document.getElementById('dots').innerHTML=products.map((p,i)=>`<button aria-label="Ver ${p.name}" data-slide="${i}"></button>`).join('');
function show(n){slide=(n+5)%5;const p=products[slide];document.getElementById('hero-art').innerHTML=art(p.type);document.getElementById('hero-name').textContent=p.name;document.getElementById('hero-category').textContent=p.category.toUpperCase();document.getElementById('hero-price').textContent=money(p.price);document.querySelector('.hero-price small').textContent=p.demo===false?'PRECIO CLP':'PRECIO DEMO';document.getElementById('hero-art').classList.toggle('has-photo',['chair-levo','cpu','gpu','board','keyboard'].includes(p.type));document.getElementById('hero-description').innerHTML=p.description;document.getElementById('spec-one').textContent=p.tag;const buy=document.getElementById('hero-buy');buy.dataset.addProduct=p.type;buy.setAttribute('aria-label','Agregar '+p.name+' al carrito');document.getElementById('slide-number').textContent=String(slide+1).padStart(2,'0');document.querySelectorAll('[data-slide]').forEach((d,i)=>d.classList.toggle('active',i===slide))}
function restart(){clearInterval(timer);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show(slide+1),3000)}document.getElementById('previous').onclick=()=>{show(slide-1);restart()};document.getElementById('next').onclick=()=>{show(slide+1);restart()};document.querySelectorAll('[data-slide]').forEach(d=>d.onclick=()=>{show(+d.dataset.slide);restart()});document.querySelector('.hero').addEventListener('mouseenter',()=>clearInterval(timer));document.querySelector('.hero').addEventListener('mouseleave',restart);document.querySelector('.hero').addEventListener('focusin',()=>clearInterval(timer));document.addEventListener('visibilitychange',()=>document.hidden?clearInterval(timer):restart());show(0);render();restart();
